import { AlertTriangle, CheckCircle2, ReceiptText, ShieldCheck } from 'lucide-react';

import type {
  AdminPaymentMethod,
  AdminBookingSettlementSnapshot,
  AdminBookingSettlementSnapshotSummary,
} from '../../../lib/admin-api';
import { adminGet } from '../../../lib/admin-api';
import { AdminFilterPanel } from '../../../components/admin-filter-panel';
import {
  AdminFormActionRow,
  AdminFormControlButton,
  AdminFormSearch,
  AdminFormShell,
} from '../../../components/admin-form-controls';
import { AdminPageTemplate } from '../../../components/admin-page-template';
import { AdminTextLink } from '../../../components/admin-text-link';
import { DateTimeText } from '../../../components/date-time-text';
import { MoneyText } from '../../../components/money-text';
import { StatusBadge, StatusBadgeFromPillClass, StatusBadgeLink } from '../../../components/status-badge';
import { dateRangeLabel } from '../../../lib/date-range';
import { shortId } from '../../../lib/admin-format';
import { FinanceDataTable } from '../finance-data-table';
import { financePersonName } from '../finance-participant-label';
import { TaxFinanceWorkflowActions } from '../tax-finance-workflow-actions';
import { FinanceListFilterLinks, FINANCE_LIST_DATE_RANGE_LINKS } from '../finance-list-filter-links';
import { FinanceListCommandBoard, FinanceListCommandCard, formatFinancePercent } from '../finance-list-command-card';
import { financeTaxCloseoutStatusPill } from '../finance-status-badge-model';
import { FinanceTablePaginationFooter } from '../finance-table-pagination-footer';
import { FinanceTablePanel } from '../finance-table-panel';
import { paymentFeeEvidenceState } from '../payment-fee-evidence-model';
import {
  BOOKING_SETTLEMENT_AUDIT_REVIEW_LINKS,
  FINANCE_ACCOUNTING_PAGE_SIZE_LINKS,
  bookingSettlementAuditDetailHref,
  buildBookingSettlementAuditExportHref,
  bookingSettlementAuditHref,
  buildBookingSettlementSnapshotApiHref,
  buildBookingSettlementSnapshotSummaryApiHref,
  buildTaxSettlementServerPagination,
  buildTaxFinanceWorkflowLinks,
  emptyBookingSettlementSummary,
  readBookingSettlementFilters,
  readMonthlyTaxClosingFilters,
  readPartnerWithholdingTaxFilters,
  reviewLabel,
} from '../tax-settlement-page-model';

type BookingSettlementAuditPageProps = {
  readonly searchParams?: Promise<Record<string, string | string[] | undefined>>;
};

export default async function BookingSettlementAuditPage({ searchParams }: BookingSettlementAuditPageProps) {
  const params = searchParams ? await searchParams : {};
  const filters = readBookingSettlementFilters(params);
  const auditQuery = readParam(params, 'q').trim();
  const monthlyFilters = readMonthlyTaxClosingFilters(params);
  const withholdingFilters = readPartnerWithholdingTaxFilters(params);
  const overviewFilters = { ...filters, page: 1, review: 'all' as const };
  const [queueSummary, overviewSummary, snapshots] = await Promise.all([
    adminGet<AdminBookingSettlementSnapshotSummary>(
      bookingSettlementApiHref(buildBookingSettlementSnapshotSummaryApiHref(filters), auditQuery),
      emptyBookingSettlementSummary(),
    ),
    adminGet<AdminBookingSettlementSnapshotSummary>(
      buildBookingSettlementSnapshotSummaryApiHref(overviewFilters),
      emptyBookingSettlementSummary(),
    ),
    adminGet<AdminBookingSettlementSnapshot[]>(
      bookingSettlementApiHref(buildBookingSettlementSnapshotApiHref(filters), auditQuery),
      [],
    ),
  ]);
  const pagination = buildTaxSettlementServerPagination(snapshots, filters, queueSummary.count);
  const tableRows = pagination.rows;
  const csvHref = bookingSettlementApiHref(buildBookingSettlementAuditExportHref(filters), auditQuery);
  const rangeScope = dateRangeLabel(filters.range);
  const periodScope = filters.period ? ` Monthly period: ${filters.period}.` : '';
  const taxReviewCount = overviewSummary.openTaxCount + overviewSummary.declaredTaxCount;
  const queueHref = (nextFilters = filters, query = auditQuery) =>
    bookingSettlementQueueHref(nextFilters, query);

  return (
    <AdminPageTemplate
      actions={
        <TaxFinanceWorkflowActions
          links={buildTaxFinanceWorkflowLinks({
            current: 'booking-settlement-audit',
            monthlyFilters,
            settlementFilters: filters,
            withholdingFilters,
          })}
        >
          <StatusBadgeLink
            download={`hands-booking-settlement-audit-${filters.range}-${filters.review}.csv`}
            href={csvHref}
            tone="success"
          >
            Export settlement CSV
          </StatusBadgeLink>
        </TaxFinanceWorkflowActions>
      }
      description="Posted booking settlement records for customer payment, Partner payout, VAT/PIT, payment fee, and company VAT audit."
      title="Booking Settlement Audit"
    >
      <FinanceListCommandBoard ariaLabel="Settlement audit command board">
        <FinanceListCommandCard
          detail={`${overviewSummary.needsActionCount} settlement record(s) need tax or processor-fee evidence review.`}
          href={queueHref({ ...filters, page: 1, review: 'open' }, '')}
          icon={AlertTriangle}
          label="Needs action"
          scope={overviewSummary.needsActionCount > 0 ? 'Review queue' : rangeScope}
          tone={overviewSummary.needsActionCount > 0 ? 'danger' : 'success'}
          value={overviewSummary.needsActionCount}
        />
        <FinanceListCommandCard
          detail={`${overviewSummary.openTaxCount} open · ${overviewSummary.declaredTaxCount} declared and awaiting payment.`}
          href={queueHref(
            {
              ...filters,
              page: 1,
              review: overviewSummary.openTaxCount > 0 ? 'tax-open' : 'declared',
            },
            '',
          )}
          icon={ShieldCheck}
          label="Tax review queue"
          scope={taxReviewCount > 0 ? 'Needs action' : rangeScope}
          tone={taxReviewCount > 0 ? 'warning' : 'success'}
          value={taxReviewCount}
        />
        <FinanceListCommandCard
          detail="CARD, MoMo, or VNPay settlements with a missing fee policy or retained fallback reason."
          href={queueHref({ ...filters, page: 1, review: 'payment-fee-evidence' }, '')}
          icon={ReceiptText}
          label="Payment fee issues"
          scope={overviewSummary.feeEvidenceIssueCount > 0 ? 'Needs action' : rangeScope}
          tone={overviewSummary.feeEvidenceIssueCount > 0 ? 'warning' : 'success'}
          value={overviewSummary.feeEvidenceIssueCount}
        />
        <FinanceListCommandCard
          detail={`${overviewSummary.resolvedCount} of ${overviewSummary.count} settlement record(s) have paid or closed tax and valid fee evidence.`}
          href={queueHref({ ...filters, page: 1, review: 'resolved' }, '')}
          icon={CheckCircle2}
          label="Resolved records"
          scope={rangeScope}
          tone="success"
          value={formatFinancePercent(overviewSummary.resolvedCount, overviewSummary.count)}
        />
      </FinanceListCommandBoard>

      <AdminFilterPanel
        className="admin-mb-16"
        description={`Showing page ${pagination.page} of ${pagination.totalPages}. Range: ${dateRangeLabel(filters.range)}. Queue: ${reviewLabel(filters.review)}.${periodScope}${auditQuery ? ` Search: ${auditQuery}.` : ''}`}
        resultLabel={`${pagination.pageSize} per page`}
        resultTone="success"
        title="Settlement audit filters"
      >
        <AdminFormShell
          action="/finance-tax/booking-settlement-audit"
          className="filter-form admin-mb-12"
          method="get"
        >
          <input name="range" type="hidden" value={filters.range} />
          <input name="review" type="hidden" value={filters.review} />
          <input name="take" type="hidden" value={filters.take} />
          {filters.period ? <input name="period" type="hidden" value={filters.period} /> : null}
          {filters.paymentMethod ? (
            <input name="paymentMethod" type="hidden" value={filters.paymentMethod} />
          ) : null}
          <AdminFormSearch
            defaultValue={auditQuery}
            label="Search settlement records"
            name="q"
            placeholder="Booking, payment, customer, partner, settlement"
          />
          <AdminFormActionRow>
            <AdminFormControlButton className="button-primary" type="submit">
              Search
            </AdminFormControlButton>
            {auditQuery ? (
              <AdminTextLink href={queueHref({ ...filters, page: 1 }, '')}>Clear</AdminTextLink>
            ) : null}
          </AdminFormActionRow>
        </AdminFormShell>
        <FinanceListFilterLinks
          groups={[
            ...(filters.period
              ? [
                  {
                    id: 'period',
                    links: [
                      {
                        active: true,
                        activePillClassName: 'pill-info' as const,
                        href: queueHref({ ...filters, page: 1 }),
                        id: filters.period,
                        label: `Period ${filters.period}`,
                      },
                      {
                        active: false,
                        activePillClassName: 'pill-info' as const,
                        href: queueHref({ ...filters, page: 1, period: undefined }),
                        id: 'all-periods',
                        label: 'All periods',
                      },
                    ],
                  },
                ]
              : []),
            {
              id: 'payment-method',
              links: BOOKING_SETTLEMENT_PAYMENT_METHOD_LINKS.map((item) => ({
                active: filters.paymentMethod === item.paymentMethod,
                activePillClassName: 'pill-info',
                href: queueHref({
                  ...filters,
                  page: 1,
                  paymentMethod: item.paymentMethod,
                }),
                id: item.paymentMethod ?? 'all-methods',
                label: item.label,
              })),
            },
            {
              className: 'admin-mt-12',
              id: 'range',
              links: FINANCE_LIST_DATE_RANGE_LINKS.map(([label, range]) => ({
                active: filters.range === range,
                activePillClassName: 'pill-info',
                href: queueHref({ ...filters, page: 1, range }),
                id: range,
                label,
              })),
            },
            {
              id: 'review',
              links: BOOKING_SETTLEMENT_AUDIT_REVIEW_LINKS.map((item) => ({
                active: filters.review === item.review,
                activePillClassName:
                  item.review === 'open' ||
                  item.review === 'tax-open' ||
                  item.review === 'declared' ||
                  item.review === 'payment-fee-evidence'
                    ? 'pill-warn'
                    : 'pill-info',
                href: queueHref({ ...filters, page: 1, review: item.review }),
                id: item.review,
                label: item.label,
              })),
            },
            {
              id: 'take',
              links: FINANCE_ACCOUNTING_PAGE_SIZE_LINKS.map((take) => ({
                active: filters.take === take,
                activePillClassName: 'pill-success',
                href: queueHref({ ...filters, page: 1, take }),
                id: take,
                label: `${take} rows`,
              })),
            },
          ]}
        />
      </AdminFilterPanel>

      <FinanceTablePanel
        grouped
        description={bookingSettlementTableDescription(filters.review)}
        resultLabel={`${pagination.totalRows} row(s)`}
        resultTone={bookingSettlementResultTone(filters.review, pagination.totalRows)}
        title={reviewLabel(filters.review)}
      >
        <FinanceDataTable
          emptyMessage="No settlement records match the current filters."
          headers={[
            'Booking / record',
            'Participants',
            'Customer payment',
            'Partner settlement',
            'HANDS revenue',
            'Review state',
            'Open',
          ]}
          rowCount={tableRows.length}
        >
          {tableRows.map((snapshot) => {
            const paymentFeeEvidence = paymentFeeEvidenceState(snapshot);
            return (
              <tr key={snapshot.id}>
                  <td>
                    <AdminTextLink href={`/bookings/${snapshot.bookingId}`}>
                      {shortId(snapshot.bookingId)}
                    </AdminTextLink>
                    <div>
                      <AdminTextLink href={bookingSettlementAuditDetailHref(snapshot.id)}>
                        Settlement record {shortId(snapshot.id)}
                      </AdminTextLink>
                    </div>
                    <div className="muted">
                      <DateTimeText value={snapshot.postedAt} />
                    </div>
                    <div className="muted">{snapshot.booking?.status ?? 'Unknown status'}</div>
                  </td>
                  <td>
                    <div>
                      <strong>{financePersonName(snapshot.customerProfile?.user, 'Unknown customer')}</strong>
                      <span className="muted"> · Customer</span>
                    </div>
                    <div className="admin-mt-6">
                      <AdminTextLink href={`/partners/${snapshot.providerProfileId}?section=full`}>
                        {snapshot.providerProfile?.displayName ??
                          financePersonName(snapshot.providerProfile?.user, 'Unknown partner')}
                      </AdminTextLink>
                      <span className="muted"> · Partner</span>
                    </div>
                  </td>
                  <td>
                    <strong>{snapshot.paymentMethod}</strong>
                    <div>
                      <MoneyText amount={snapshot.customerPaymentAmount} currency={snapshot.currency} />
                    </div>
                    <div className="muted">
                      Processing{' '}
                      <MoneyText amount={snapshot.paymentProcessingFee} currency={snapshot.currency} />
                    </div>
                  </td>
                  <td>
                    <strong>
                      <MoneyText amount={snapshot.partnerPayoutAmount} currency={snapshot.currency} />
                    </strong>
                    <div className="muted">
                      Withheld{' '}
                      <MoneyText amount={snapshot.partnerWithholdingTotal} currency={snapshot.currency} />
                    </div>
                    <div className="muted">
                      VAT <MoneyText amount={snapshot.partnerVatAmount} currency={snapshot.currency} /> · PIT{' '}
                      <MoneyText amount={snapshot.partnerPitAmount} currency={snapshot.currency} />
                    </div>
                  </td>
                  <td>
                    <strong>
                      <MoneyText amount={snapshot.platformFeeGross} currency={snapshot.currency} />
                    </strong>
                    <div className="muted">
                      Net <MoneyText amount={snapshot.platformFeeNetRevenue} currency={snapshot.currency} />
                    </div>
                    <div className="muted">
                      Output VAT{' '}
                      <MoneyText amount={snapshot.companyOutputVat} currency={snapshot.currency} />
                    </div>
                  </td>
                  <td>
                    <StatusBadgeFromPillClass pillClass={financeTaxCloseoutStatusPill(snapshot.taxStatus)}>
                      Tax {settlementTaxStatusLabel(snapshot.taxStatus)}
                    </StatusBadgeFromPillClass>
                    <div className="admin-mt-6">
                      <StatusBadge tone={paymentFeeEvidence.tone}>{paymentFeeEvidence.label}</StatusBadge>
                    </div>
                    <div className="muted admin-mt-6">{snapshot.monthlyPeriod}</div>
                    <div className="muted">{settlementStatusLabel(snapshot.settlementStatus)}</div>
                  </td>
                  <td>
                    <AdminTextLink href={bookingSettlementAuditDetailHref(snapshot.id)}>
                      Open detail
                    </AdminTextLink>
                  </td>
              </tr>
            );
          })}
        </FinanceDataTable>
        <FinanceTablePaginationFooter
          ariaLabel="Booking settlement audit pages"
          hrefForPage={(page) => queueHref({ ...filters, page })}
          pagination={pagination}
        />
      </FinanceTablePanel>
    </AdminPageTemplate>
  );
}

const BOOKING_SETTLEMENT_PAYMENT_METHOD_LINKS: readonly {
  readonly label: string;
  readonly paymentMethod?: AdminPaymentMethod;
}[] = [
  { label: 'All methods' },
  { label: 'Card', paymentMethod: 'CARD' },
  { label: 'MoMo', paymentMethod: 'MOMO' },
  { label: 'VNPay', paymentMethod: 'VNPAY' },
  { label: 'Customer wallet', paymentMethod: 'CUSTOMER_WALLET' },
  { label: 'Cash', paymentMethod: 'CASH' },
  { label: 'Bank transfer', paymentMethod: 'BANK_TRANSFER' },
  { label: 'Manual', paymentMethod: 'MANUAL' },
];

function bookingSettlementApiHref(href: string, query: string) {
  return query ? appendQueryParam(href, 'q', query) : href;
}

function bookingSettlementQueueHref(
  filters: Parameters<typeof bookingSettlementAuditHref>[0],
  query: string,
) {
  return bookingSettlementApiHref(bookingSettlementAuditHref(filters), query);
}

function bookingSettlementTableDescription(
  review: Parameters<typeof bookingSettlementAuditHref>[0]['review'],
) {
  if (review === 'open') {
    return 'Oldest settlement records with open or declared tax, or missing processor-fee evidence, appear first.';
  }
  if (review === 'tax-open') {
    return 'Settlement tax records that have not yet been declared, ordered from oldest to newest.';
  }
  if (review === 'declared') {
    return 'Declared settlement tax records awaiting payment or closing, ordered from oldest to newest.';
  }
  if (review === 'payment-fee-evidence') {
    return 'CARD, MoMo, and VNPay settlements with missing policy evidence or a retained fallback reason.';
  }
  if (review === 'resolved') {
    return 'Paid or closed settlement records with valid processor-fee evidence.';
  }
  if (review === 'reversed') {
    return 'Historical reversed settlement records retained for audit.';
  }
  return 'Posted settlement records for bounded historical lookup.';
}

function bookingSettlementResultTone(
  review: Parameters<typeof bookingSettlementAuditHref>[0]['review'],
  count: number,
) {
  if (
    review === 'open' ||
    review === 'tax-open' ||
    review === 'declared' ||
    review === 'payment-fee-evidence'
  ) {
    return count > 0 ? 'warning' as const : 'success' as const;
  }
  if (review === 'resolved') return 'success' as const;
  return 'info' as const;
}

function settlementTaxStatusLabel(status: AdminBookingSettlementSnapshot['taxStatus']) {
  return status.charAt(0) + status.slice(1).toLowerCase();
}

function settlementStatusLabel(status: AdminBookingSettlementSnapshot['settlementStatus']) {
  return status.charAt(0) + status.slice(1).toLowerCase();
}

function appendQueryParam(href: string, key: string, value: string) {
  const url = new URL(href, 'http://localhost');
  url.searchParams.set(key, value);
  return `${url.pathname}${url.search}`;
}

function readParam(params: Record<string, string | string[] | undefined>, key: string) {
  const value = params[key];
  return Array.isArray(value) ? (value[0] ?? '') : (value ?? '');
}
